define("local_sentientia_exams/exam_actions", [
    "core_form/modalform",
    "core/str",
    "core/notification",
    "core/ajax"
], function(ModalForm, Str, Notification, Ajax) {
    "use strict";

    var openExamForm = function(examid, returnFocus) {
        var titleKey = (examid === 0) ? "addexam" : "editexam";
        Str.get_string(titleKey, "local_sentientia_exams").then(function(title) {
            var modalForm = new ModalForm({
                formClass: "local_sentientia_exams\\form\\edit_exam",
                args: {examid: examid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var message = (event.detail && event.detail.message) || "Saved.";
                Notification.addNotification({message: message, type: "success"});
                window.location.reload();
            });
            modalForm.show();
            return null;
        }).catch(Notification.exception);
    };

    var confirmStatus = function(examid, name, makeActive, returnFocus) {
        var titleKey = makeActive ? "activateexam" : "deactivateexam";
        var msgKey = makeActive ? "confirmactivate" : "confirmdeactivate";
        Promise.all([
            Str.get_string(titleKey, "local_sentientia_exams"),
            Str.get_string(msgKey, "local_sentientia_exams", name),
            Str.get_string("examstatuschanged", "local_sentientia_exams")
        ]).then(function(strings) {
            Notification.confirm(strings[0], strings[1], strings[0], null, function() {
                Ajax.call([{methodname: "local_sentientia_exams_toggle_status",
                            args: {examid: examid, active: makeActive}}])[0]
                    .then(function() {
                        Notification.addNotification({message: strings[2], type: "success"});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
            });
            if (returnFocus) setTimeout(function() { returnFocus.focus(); }, 100);
            return null;
        }).catch(Notification.exception);
    };

    var confirmDelete = function(examid, name, returnFocus) {
        Promise.all([
            Str.get_string("deleteexam", "local_sentientia_exams"),
            Str.get_string("confirmdelete", "local_sentientia_exams", name),
            Str.get_string("delete", "core"),
            Str.get_string("examdeleted", "local_sentientia_exams")
        ]).then(function(strings) {
            Notification.deleteCancelPromise(strings[0], strings[1], strings[2], returnFocus).then(function() {
                Ajax.call([{methodname: "local_sentientia_exams_delete_exam",
                            args: {examid: examid}}])[0]
                    .then(function() {
                        Notification.addNotification({message: strings[3], type: "success"});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
                return true;
            }, function() { return null; });
            return null;
        }).catch(Notification.exception);
    };

    var handleClick = function(event) {
        var trigger = event.target.closest("[data-action]");
        if (!trigger) return;
        var action = trigger.dataset.action;
        var examid = parseInt(trigger.dataset.examid || "0", 10);
        var name = trigger.dataset.name || "this exam";
        switch (action) {
            case "create-exam":     event.preventDefault(); openExamForm(0, trigger); break;
            case "edit-exam":       event.preventDefault(); openExamForm(examid, trigger); break;
            case "activate-exam":   event.preventDefault(); confirmStatus(examid, name, true, trigger); break;
            case "deactivate-exam": event.preventDefault(); confirmStatus(examid, name, false, trigger); break;
            case "delete-exam":     event.preventDefault(); confirmDelete(examid, name, trigger); break;
        }
    };

    return {
        init: function() {
            var root = document.querySelector('[data-region="airpay-exams"]') || document.body;
            if (root.dataset.airpayExamsInit === "1") return;
            root.dataset.airpayExamsInit = "1";
            root.addEventListener("click", handleClick);
        }
    };
});
